// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *DocumentEntry) CalcSums(fieldNames ...string) error {
	tableName := fmt.Sprintf("%s$%s", t.company, DocumentEntryTableName)
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "table_id":
			column = "table_id"
		case "no_of_records":
			column = "no_of_records"
		case "entry_no":
			column = "entry_no"
		case "page_id":
			column = "page_id"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of Document_Entry", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums Document_Entry.%s: %w", column, err)
		}
		switch column {
		case "table_id":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Document_Entry.%s: %w", column, err)
			}
			t.Table_id = int(f)
		case "no_of_records":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Document_Entry.%s: %w", column, err)
			}
			t.No_of_records = int(f)
		case "entry_no":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Document_Entry.%s: %w", column, err)
			}
			t.Entry_no = int(f)
		case "page_id":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Document_Entry.%s: %w", column, err)
			}
			t.Page_id = int(f)
		}
	}
	return nil
}

// LockTable locks the table until the transaction ends (classic LOCKTABLE): on Postgres a
